"use strict";function t(t,e="YYYY-MM-DD"){if(!t)return"";const r=new Date(t);if(isNaN(r.getTime()))return String(t).slice(0,10);const n=t=>String(t).padStart(2,"0"),o={YYYY:r.getFullYear(),MM:n(r.getMonth()+1),DD:n(r.getDate()),HH:n(r.getHours()),mm:n(r.getMinutes()),ss:n(r.getSeconds())};let i=e;for(const[s,a]of Object.entries(o))i=i.replace(s,a);return i}exports.formatDate=t,exports.relativeTime=function(e){if(!e)return"";const r=Date.now()-new Date(e).getTime(),n=Math.floor(r/6e4);if(n<1)return"刚刚";if(n<60)return`${n}分钟前`;const o=Math.floor(n/60);if(o<24)return`${o}小时前`;const i=Math.floor(o/24);return i<7?`${i}天前`:t(e,"MM-DD")};
